    StandingResponse before = raceService.getResults(RACE);
    assertThat(before.entries().getFirst().penaltyMs()).isEqualTo(10_000L);
    assertThat(before.entries().getFirst().servedMs()).isZero();
    assertThat(before.entries().getFirst().totalTimeMs()).isEqualTo(110_000L);

    ServiceResult confirmed = raceService.confirmPenaltyCredit(RACE, "c-1",
            new ConfirmPenaltyCreditRequest("ref-2", version(), "req-confirm-1"));
    assertThat(confirmed.status()).isEqualTo(200);
    PenaltyCreditResponse confirmedCredit = (PenaltyCreditResponse) confirmed.body();
    assertThat(confirmedCredit.status()).isEqualTo(PenaltyCreditStatus.CONFIRMED);
    assertThat(confirmedCredit.creditedMs()).isEqualTo(6_000L);
    assertThat(confirmedCredit.confirmedBy()).isEqualTo("ref-2");
    assertThat(confirmedCredit.confirmedAt()).isEqualTo(FixedClockTestConfig.FIXED_INSTANT.toEpochMilli());

    StandingResponse after = raceService.getResults(RACE);
    ResultEntryResponse entry = after.entries().getFirst();
    assertThat(entry.penaltyMs()).isEqualTo(10_000L);   // 原罚时不改写
    assertThat(entry.servedMs()).isEqualTo(6_000L);    // 已执行量
