        assertThat(((PenaltyCreditResponse) second.body()).creditedMs()).isZero();
        assertThat(raceService.getResults(RACE).entries().getFirst().totalTimeMs())
                .isEqualTo(100_000L);
    }

    @Test
    void 确认裁判必须与登记裁判不同() {
        seedRaceWithPenalty(100_000L, 10_000L);
