                new ConfirmPenaltyCreditRequest("ref-1", version(), "req-cf1")))
                .isInstanceOf(UnprocessableEntityException.class);
        assertThat(repository.findCredit("c-1").orElseThrow().status())
                .isEqualTo(PenaltyCreditStatus.PENDING);
    }
